            const problems = Array.from({ length: 9 }, () => {
              const hour = Math.floor(rng() * 12) + 1
              const minute = Math.floor(rng() * 60)
              return { hour, minute }
            })

            const renderClock = (h: number, m: number) => {
              // Clock logic
              const mDeg = m * 6
              const hDeg = (h % 12) * 30 + m * 0.5

              const tickMarks = Array.from({ length: 12 }).map((_, i) => {
                const angle = i * 30
                const x1 = 50 + 40 * Math.cos((angle - 90) * Math.PI / 180)
                const y1 = 50 + 40 * Math.sin((angle - 90) * Math.PI / 180)
                const x2 = 50 + 45 * Math.cos((angle - 90) * Math.PI / 180)
                const y2 = 50 + 45 * Math.sin((angle - 90) * Math.PI / 180)
                return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#334155" strokeWidth={i % 3 === 0 ? 3 : 1} />
              })

              return (
                <svg viewBox="0 0 100 100" className="w-32 h-32">
                  <circle cx="50" cy="50" r="48" fill="white" stroke="#334155" strokeWidth="4" />
                  {tickMarks}
                  {/* Numbers */}
                  {[12, 3, 6, 9].map(n => {
                    const angle = (n * 30 - 90) * Math.PI / 180
                    const x = 50 + 34 * Math.cos(angle)
                    const y = 50 + 34 * Math.sin(angle)
                    return <text key={n} x={x} y={y + 2} textAnchor="middle" dominantBaseline="middle" className="text-[10px] font-bold fill-slate-700">{n}</text>
                  })}

                  {/* Hour Hand */}
                  <line x1="50" y1="50"
                    x2={50 + 25 * Math.cos((hDeg - 90) * Math.PI / 180)}
                    y2={50 + 25 * Math.sin((hDeg - 90) * Math.PI / 180)}
                    stroke="#1e293b" strokeWidth="3" strokeLinecap="round" />

                  {/* Minute Hand */}
                  <line x1="50" y1="50"
                    x2={50 + 38 * Math.cos((mDeg - 90) * Math.PI / 180)}
                    y2={50 + 38 * Math.sin((mDeg - 90) * Math.PI / 180)}
                    stroke="#475569" strokeWidth="2" strokeLinecap="round" />

                  <circle cx="50" cy="50" r="2" fill="#ef4444" />
                </svg>
              )
            }

